[
  {
    "statement": "Creating groove habitats and small protrusions, ridges, or ledges on intertidal artificial structures appears to be a cost-effective method for enhancing biodiversity.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Sixteen studies found that creating groove habitats and small protrusions, ridges, or ledges on intertidal artificial structures increased species richness and diversity.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Sixteen studies found that creating groove habitats and small protrusions, ridges, or ledges on intertidal artificial structures supported species absent from smooth surfaces.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Sixteen studies found that creating groove habitats and small protrusions, ridges, or ledges on intertidal artificial structures altered community composition.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Some studies showed mixed biodiversity results from adding features to artificial structures, with outcomes depending on factors like depth, shore level, and site conditions.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "The majority of studies found that creating groove habitats and small protrusions, ridges, or ledges on intertidal artificial structures had positive effects on biodiversity.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Creating small protrusions alone on intertidal artificial structures is another cost-effective option for enhancing biodiversity.",
    "citations": [
      "3462"
    ]
  },
  {
    "statement": "Studies in Singapore found that creating small protrusions on intertidal artificial structures increased species richness.",
    "citations": [
      "3462"
    ]
  },
  {
    "statement": "Reducing the slope of intertidal artificial structures was also examined as a method to enhance biodiversity.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "One study found that reducing the slope of intertidal artificial structures increased species richness when combined with rock pools.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "A study on reducing the slope of intertidal artificial structures found that individual species abundances were not consistently enhanced.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "Surface modification techniques are likely more cost-effective than complex engineering solutions for enhancing biodiversity on intertidal artificial structures.",
    "citations": []
  },
  {
    "statement": "Surface modification techniques involve relatively simple alterations during the construction or retrofitting of existing structures.",
    "citations": []
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects of creating crevice habitats (>50 mm) on subtidal artificial structures on fish abundance.",
    "citations": []
  },
  {
    "statement": "No studies were found that evaluated the effects of creating crevice habitats (>50 mm) on subtidal artificial structures on any biodiversity outcomes.",
    "citations": []
  },
  {
    "statement": "For crevice habitats specifically, there is no evidence to indicate whether or not this intervention has any desirable or harmful effects on fish populations.",
    "citations": []
  },
  {
    "statement": "Creating large swimthrough habitats (>100 mm) on subtidal artificial structures increased overall fish abundance.",
    "citations": [
      "3456"
    ]
  },
  {
    "statement": "Creating large swimthrough habitats (>100 mm) on subtidal artificial structures increased species richness.",
    "citations": [
      "3456"
    ]
  },
  {
    "statement": "Individual species responses to the creation of large swimthrough habitats varied.",
    "citations": [
      "3456"
    ]
  },
  {
    "statement": "Creating hole habitats (>50 mm), which are similar to crevices, showed mixed effects on fish abundance.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "One study found that creating hole habitats did not increase fish abundances.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "Another study found that creating hole habitats had mixed effects on fish abundance depending on the species group.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "The lack of specific studies on crevice habitats (>50 mm) means there is currently no direct evidence about the effects of these habitats on fish abundance.",
    "citations": []
  }
]

[
  {
    "statement": "The available research indicates a significant knowledge gap regarding the effects of eco-engineering interventions on marine mammal populations.",
    "citations": []
  },
  {
    "statement": "No studies were found that evaluated the effects on marine mammal populations from creating large protrusions on subtidal artificial structures.",
    "citations": [
      "3443"
    ]
  },
  {
    "statement": "There is currently no evidence to indicate whether creating large protrusions on subtidal artificial structures has any desirable or harmful effects on marine mammals.",
    "citations": [
      "3443"
    ]
  },
  {
    "statement": "For related eco-engineering interventions, the evidence regarding effects on marine mammals is also limited.",
    "citations": []
  },
  {
    "statement": "Creating artificial habitat specifically for marine and freshwater mammals has not been studied.",
    "citations": [
      "2921"
    ]
  },
  {
    "statement": "There is no evidence available to assess the effectiveness or harmful impacts of creating artificial habitats for marine and freshwater mammals.",
    "citations": [
      "2921"
    ]
  },
  {
    "statement": "Leaving anthropogenic structures in place after decommissioning has not been evaluated for effects on marine mammal populations.",
    "citations": [
      "2922"
    ]
  },
  {
    "statement": "The studies that do exist on eco-engineering interventions focus primarily on invertebrate and algal communities.",
    "citations": []
  },
  {
    "statement": "Research on creating grooves and small protrusions on subtidal artificial structures found effects on macroalgae and invertebrate communities, but these studies did not examine impacts on marine mammals.",
    "citations": [
      "3452"
    ]
  },
  {
    "statement": "One study on repurposing obsolete offshore structures as artificial reefs documented colonization by invertebrate species but did not assess marine mammal interactions.",
    "citations": [
      "2262"
    ]
  },
  {
    "statement": "A comprehensive lack of evidence suggests that the effects of eco-engineering interventions, including the creation of large protrusions on subtidal artificial structures, remain unstudied in relation to marine mammal populations.",
    "citations": []
  }
]

[
  {
    "statement": "There is limited information specifically addressing public perceptions of reducing the slope of intertidal artificial structures for biodiversity enhancement.",
    "citations": []
  },
  {
    "statement": "The available evidence on reducing the slope of intertidal artificial structures focuses primarily on ecological effects rather than social or public acceptance aspects.",
    "citations": []
  },
  {
    "statement": "Two studies examined the ecological effects of reducing the slope of intertidal artificial structures in southeast Australia.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "The two studies in southeast Australia showed mixed results for biodiversity outcomes.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "No specific studies documenting public perceptions of reducing the slope of intertidal artificial structures for biodiversity enhancement were identified.",
    "citations": []
  },
  {
    "statement": "No specific studies documenting stakeholder views on reducing the slope of intertidal artificial structures for biodiversity enhancement were identified.",
    "citations": []
  },
  {
    "statement": "No specific studies documenting social acceptance of reducing the slope of intertidal artificial structures for biodiversity enhancement were identified.",
    "citations": []
  }
]

[
  {
    "statement": "Multiple habitat modification techniques show promise for cost-effectively increasing biodiversity on subtidal artificial structures.",
    "citations": []
  },
  {
    "statement": "Creating textured surfaces with small-scale features of 1 mm or less demonstrated positive effects on macroalgae and invertebrate community composition.",
    "citations": [
      "3449"
    ]
  },
  {
    "statement": "Creating textured surfaces with small-scale features of 1 mm or less demonstrated positive effects on species richness.",
    "citations": [
      "3449"
    ]
  },
  {
    "statement": "Small habitat features, such as pits, grooves, flexible habitats, and protrusions, showed mixed but generally positive results for increasing invertebrate and fish diversity.",
    "citations": [
      "3450",
      "3453",
      "3455",
      "3448"
    ]
  },
  {
    "statement": "Small habitat features between 1 and 50 mm demonstrated improved community composition and abundance for various species groups.",
    "citations": [
      "3450",
      "3453",
      "3455",
      "3448"
    ]
  },
  {
    "statement": "Creating large swimthrough habitats greater than 100 mm effectively increased fish species richness and abundance.",
    "citations": [
      "3456"
    ]
  },
  {
    "statement": "Managing or restricting harvesting on artificial structures showed higher fish species richness and abundance.",
    "citations": [
      "3457"
    ]
  },
  {
    "statement": "There is no evidence available for the effectiveness of reducing an artificial structure's slope.",
    "citations": []
  },
  {
    "statement": "There is no evidence available for the effectiveness of removing non-native species from artificial structures.",
    "citations": []
  },
  {
    "statement": "There is no evidence available for the effectiveness of using environmentally-sensitive materials for artificial structures.",
    "citations": []
  },
  {
    "statement": "Interventions such as reducing structure slope, removing non-native species, or using environmentally-sensitive materials lack sufficient study data.",
    "citations": []
  }
]

[
  {
    "statement": "No studies were found that directly evaluated the effects of creating crevice habitats (>50 mm) on intertidal artificial structures on biodiversity.",
    "citations": [
      "3437"
    ]
  },
  {
    "statement": "There is currently no scientific evidence to indicate whether creating crevice habitats (>50 mm) has any desirable or harmful effects on biodiversity.",
    "citations": []
  },
  {
    "statement": "Studies on groove habitats (1-50 mm) on intertidal artificial structures showed mixed results.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Some studies on groove habitats (1-50 mm) found increases in species richness or abundance, while others found no effects.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Creating hole habitats (>50 mm) on intertidal artificial structures was found to alter community composition.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Creating hole habitats (>50 mm) on intertidal artificial structures was found to increase species richness and diversity.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Creating small adjoining cavities or 'swimthrough' habitats (≤100 mm) showed mixed effects on invertebrate communities.",
    "citations": [
      "3468"
    ]
  },
  {
    "statement": "The absence of evidence for crevice habitats (>50 mm) indicates a research gap.",
    "citations": []
  },
  {
    "statement": "The intervention of creating crevice habitats (>50 mm) has not been empirically tested in the scientific literature.",
    "citations": []
  }
]

[
  {
    "statement": "The available evidence in the marine conservation literature focuses on the biodiversity effects of creating 'rock pools' on intertidal artificial structures.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "There is limited information on the long-term structural integrity impacts of creating 'rock pools' on intertidal artificial structures.",
    "citations": []
  },
  {
    "statement": "Studies examining biodiversity effects found that created rock pools supported different macroalgae, invertebrate, and fish communities compared with structure surfaces without pools.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "No direct evidence was found regarding the structural integrity impacts of creating rock pools on engineering materials.",
    "citations": []
  },
  {
    "statement": "Related research on environmentally-sensitive materials tested alternative concrete compositions.",
    "citations": [
      "3469"
    ]
  },
  {
    "statement": "The testing of alternative concrete compositions found mixed effects on species colonization.",
    "citations": [
      "3469"
    ]
  },
  {
    "statement": "Research into alternative concrete compositions did not address structural durability concerns.",
    "citations": [
      "3469"
    ]
  },
  {
    "statement": "One study reported that wave-sheltered pools filled with sediment within two years.",
    "citations": []
  },
  {
    "statement": "The filling of pools with sediment suggests that pool modifications may require maintenance in certain conditions.",
    "citations": []
  },
  {
    "statement": "The potential need for maintenance on pools due to sediment relates to habitat function rather than structural engineering.",
    "citations": []
  }
]

[
  {
    "statement": "Both creating textured surfaces and transplanting organisms onto subtidal structures show mixed effectiveness for increasing invertebrate abundance.",
    "citations": []
  },
  {
    "statement": "Some studies found that textured surfaces of 1 mm or less showed no increase in the combined abundance of macroalgae and non-mobile invertebrates.",
    "citations": []
  },
  {
    "statement": "One study that combined textured surfaces with environmentally-sensitive material did show increased abundance and biomass.",
    "citations": []
  },
  {
    "statement": "Eleven studies that examined transplanting organisms found this approach had varied results.",
    "citations": []
  },
  {
    "statement": "Two studies that specifically looked at invertebrate abundance found that transplanting sea urchins reduced non-native species cover on kelps.",
    "citations": []
  },
  {
    "statement": "Transplanting corals was found to increase coral cover on structure surfaces.",
    "citations": []
  },
  {
    "statement": "Survival rates for transplanted organisms were variable depending on species, environmental conditions, and protection measures.",
    "citations": []
  },
  {
    "statement": "The evidence does not clearly indicate that either creating textured surfaces or transplanting organisms is consistently more effective than the other for increasing overall invertebrate abundance on subtidal artificial structures.",
    "citations": []
  }
]
